def build() -> dict:
    terms = []
    for tid, ctx, units, en, en_syn, en_def, tr in T:
        e = {"id": tid, "context": ctx, "units": units, "en": {"term": en, "synonyms": en_syn, "definition": en_def}}
        for lang in LANGS:
            v = tr[lang]
            e[lang] = {"term": v[0], "synonyms": v[1], "match": v[2], "definition": v[3]}
            if len(v) > 4:
                e[lang]["pronunciation"] = v[4]
        terms.append(e)
    return {"schema": "skytrace.terms/1", "method": "TERM-1", "version": "0.10.0",
            "status": "machine-translated by an AI model; not reviewed by a native speaker or a domain expert",
            "pronunciation": "romanised transliteration for Bangla and Hindi (not IPA)",
            "languages": ["en"] + LANGS, "n": len(terms), "terms": terms}


def main() -> int:
    text = json.dumps(build(), ensure_ascii=False, indent=1) + "\n"
    if "--check" in sys.argv:
        ok = OUT.exists() and OUT.read_text(encoding="utf-8") == text
        print("terms.json up to date" if ok else "terms.json is out of date: run python scripts/i18n_terms.py")
        return 0 if ok else 1
    OUT.write_text(text, encoding="utf-8")
    print(f"{len(T)} terms")
    return 0


if __name__ == "__main__":
    sys.exit(main())
